ddl:
  CREATE OR REPLACE EDITIONABLE TYPE "W4O_<run_id>"."TY_POINT_<run_id>" AS OBJECT (
    X NUMBER,
    Y NUMBER,
    MEMBER FUNCTION NORM2 RETURN NUMBER
);
CREATE OR REPLACE EDITIONABLE TYPE BODY "W4O_<run_id>"."TY_POINT_<run_id>" AS
    MEMBER FUNCTION NORM2 RETURN NUMBER IS
    BEGIN
        RETURN X * X + Y * Y;
    END;
END;
